traces.query:
PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?pattern .
  ?pattern net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>

SELECT ?rootAlarm ?alarmType ?severity ?triggeredAt
WHERE {
  net:Incident_DDoS net:composedOf ?rootAlarm .
  ?rootAlarm net:alarmType ?alarmType ;
             net:hasSeverity ?severity ;
             net:triggeredAt ?triggeredAt .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?rootAlarm .
  }
}

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  ?cause net:causallyLinkedTo net:Alarm_WebTimeout .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  ?cause net:causallyLinkedTo net:Alarm_Latency .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label
WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(?intermediate) AS ?pathCount)
WHERE {
  net:Alarm_CPU net:causallyLinkedTo+ net:Alarm_WebTimeout .
  OPTIONAL { net:Alarm_CPU net:causallyLinkedTo ?intermediate . }
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(*) AS ?pathExists) WHERE {
  net:Alarm_Latency net:causallyLinkedTo+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?anyAlarm net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  ?cause net:causallyLinkedTo ?effect .
  FILTER(?cause IN (net:Alarm_Latency, net:Alarm_PacketDrop) && ?effect IN (net:Alarm_Latency, net:Alarm_PacketDrop) && ?cause != ?effect)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
  FILTER NOT EXISTS { ?alarm net:causallyLinkedTo net:Alarm_PacketDrop }
}

PREFIX net: <http://example.org/network#>
SELECT DISTINCT ?device ?deviceLabel WHERE {
  ?alarmA a net:Alarm ;
          net:affectsDevice ?device ;
          rdfs:label ?alarmLabelA .
  ?alarmB a net:Alarm ;
          net:affectsDevice ?otherDevice .
  ?alarmA net:causallyLinkedTo ?alarmB .
  FILTER NOT EXISTS {
    ?prevAlarm net:causallyLinkedTo ?alarmA .
  }
  ?device rdfs:label ?deviceLabel .
} ORDER BY ?deviceLabel LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?affectedAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?affectedAlarm .
  ?affectedAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?avoidedAlarm ?avoidedAlarmLabel WHERE {
  net:Alarm_CPU net:causallyLinkedTo ?avoidedAlarm .
  OPTIONAL { ?avoidedAlarm rdfs:label ?avoidedAlarmLabel . }
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?affectedAlarm) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo ?affectedAlarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?alarmLabel
WHERE {
  # Identify the CPU overload alarm
  ?cpu a net:Alarm ;
       net:alarmType "CPU_OVERLOAD" ;
       rdfs:label ?cpuLabel .

  # Alarms that are part of the incident
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm rdfs:label ?alarmLabel .

  # Exclude the CPU alarm itself
  FILTER (?alarm != ?cpu)

  # Exclude alarms that are causally caused by the CPU alarm
  FILTER NOT EXISTS { ?cpu net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?effect .
  FILTER(?effect = net:Alarm_WebTimeout)
  BIND(net:Alarm_Latency AS ?cause)
}
